/**
 * Content of the Help and guide page, written in plain words for people who are not marketers or developers.
 * Every guide is a short list of steps. A step may name a drawn example picture (`shot`); real screenshots dropped into
 * public/help/shots/<shot>.png replace the drawn example automatically.
 */
export type ShotId = 'signin' | 'connect' | 'kpis' | 'trend' | 'table' | 'heatmap' | 'score' | 'form' | 'chat' | 'share' | 'tabs' | 'reviews' | 'keywords' | 'alert' | 'sidebar';
export interface Step { text: string; shot?: ShotId }
export type GroupId = 'start' | 'reports' | 'build' | 'ai' | 'seo' | 'local' | 'team';
export interface Guide { id: string; group: GroupId; title: string; summary: string; path?: string; steps: Step[]; tips?: string[]; limits?: string[] }
export interface Faq { q: string; a: string }
export interface Term { word: string; meaning: string }

