export const FAQS: Faq[] = [
  { q: 'Is it safe to connect my Google account?', a: 'AdLens only asks to read your Analytics and Search Console numbers. It cannot change anything, and you can disconnect any time on the Connections page. Your connection details are stored encrypted on the server and never shown in your browser.' },
  { q: 'Why do I see sample data?', a: 'Until you connect a source, AdLens shows made-up numbers so you can look around. Connect Google (and Meta if you run ads) and the real numbers replace them. A badge and the colour of the dot in the left menu tell you which you are looking at.' },
  { q: 'My numbers are empty or look wrong. What do I check?', a: 'First check the project you have selected at the top of the left menu. Then check Connections: the right Google Analytics website and Search Console site must be chosen. Finally check the dates. Search Console data arrives about two days late.' },
  { q: 'Why is "average position" a small number when things are good?', a: 'Position 1 is the top of Google\'s first page. A smaller number is better. Position 11 or higher is the second page.' },
  { q: 'What is the difference between visits, users and impressions?', a: 'Visits (sessions) and users come from Analytics and count people on your website. Impressions come from Search Console and count how often your page was shown in Google results, whether or not anyone clicked.' },
  { q: 'What does "uses one AI question" mean?', a: 'Your plan includes a number of AI questions each month for the built-in AI. A question is given back if the AI fails. Using your own AI agent with your own key does not use these.' },
  { q: 'Can the AI make mistakes?', a: 'Yes. Treat answers as a starting point and check important figures against the report. The AI only sees the numbers and text AdLens gives it.' },
  { q: 'Who can see my shared links?', a: 'Anyone who has the link, until it expires or you switch it off. Share only what you are happy for them to see, including tables you uploaded.' },
  { q: 'Why does search volume or cost show "needs data source"?', a: 'Google does not give these numbers for free. Connect your own market-data provider on the Connections page, "Market data provider" and they fill in automatically.' },
  { q: 'Who pays for the market-data provider?', a: 'You do, directly to the provider (for example DataForSEO). AdLens adds no charge on top and caps daily lookups to protect you from accidents.' },
  { q: 'Why did a Map scan ask me to confirm?', a: 'Each spot and phrase is one paid lookup at your provider. A 5 by 5 grid with 10 phrases is 250 lookups, roughly 50 cents. The confirmation shows the exact number first.' },
  { q: 'Will AdLens post replies to my reviews by itself?', a: 'No. The AI writes a draft; a person must read it and press "Approve and post". Nothing is sent to Google before that.' },
  { q: 'Why does Business Profile say Google has not approved access?', a: 'Google only lets approved apps use the Business Profile API. The owner of this AdLens must apply once for the whole platform. Until Google approves, the Map rank tracker and everything else still work.' },
  { q: 'Is AI visibility the same as asking ChatGPT myself?', a: 'No. It asks one AI assistant the same questions on a schedule you choose and checks the answers for your brand. AI answers vary, so look at the trend over several runs, not a single result.' },
  { q: 'The speed test says Google is busy.', a: 'Google limits free tests. The owner can add a free PageSpeed key in the server settings to raise the limit.' },
  { q: 'I never got the verification email.', a: 'Check spam or junk. Then sign in again and press the resend button on the verification page. If it still does not arrive, tell the owner of this AdLens; the email sender may need setting up.' },
  { q: 'How do I get my data out?', a: 'Every table has a download button for a CSV file, and reports can be downloaded as a PDF from the Share dialog.' },
  { q: 'How do I delete my account?', a: 'Settings, Security, Danger zone, "Delete account". It removes your profile, workspaces you own alone, their projects, saved reports and connections. It cannot be undone.' },
  { q: 'Can I use AdLens on my phone?', a: 'Yes. The layout adapts to small screens, and you can install it like an app from your browser menu ("Add to home screen").' },
  { q: 'How do I ask for help or report a problem?', a: 'Tell the owner of your AdLens, or press the feedback link if your owner has added one. Mention the page you were on and what you pressed.' },
];

export const GLOSSARY: Term[] = [
  { word: 'Google Analytics 4 (GA4)', meaning: 'Google\'s free tool that counts visitors to your website and what they do.' },
  { word: 'Search Console', meaning: 'Google\'s free tool that shows how your website appears in Google search.' },
  { word: 'Impression', meaning: 'One time your page was shown in Google results.' },
  { word: 'Click rate (CTR)', meaning: 'Clicks divided by impressions: how often people who saw you clicked.' },
  { word: 'Position', meaning: 'Where you appear in the results. 1 is the very top.' },
  { word: 'Session', meaning: 'One visit to your website.' },
  { word: 'Keyword', meaning: 'A word or phrase people type into a search box.' },
  { word: 'Keyword difficulty', meaning: 'How hard it is to rank for a phrase, from 0 (easy) to 100 (very hard).' },
  { word: 'CPC', meaning: 'Cost per click: what an advertiser typically pays when someone clicks a Google ad.' },
  { word: 'Backlink', meaning: 'A link from another website to yours. Good ones help you rank.' },
  { word: 'Sitemap', meaning: 'A file that lists the pages of your website for search engines.' },
  { word: 'Crawler', meaning: 'A robot that reads websites, such as Googlebot.' },
  { word: 'UTM tag', meaning: 'A small label added to a link so Analytics knows which campaign sent the visitor.' },
  { word: 'Core Web Vitals', meaning: 'Google\'s measures of how fast and steady a page feels to real visitors.' },
  { word: 'Map pack', meaning: 'The top three businesses Google shows on the map for a local search.' },
  { word: 'Place id', meaning: 'The code Google uses for your business listing.' },
  { word: 'Webhook', meaning: 'A web address another service calls to pass information, for example into Slack.' },
  { word: 'Project / workspace', meaning: 'A project is one website. A workspace is your team\'s home that holds projects and people.' },
];
